const findOptionByScrolling = async (page, endpoint) => {
  let tries = 0; const maxTries = 5;
  const dropdown = page.getByTestId('global-search-select-dropdown').locator('.rc-virtual-list-holder');
  const option = page.getByTestId(`global-search-select-option-${filterName}`);
  while (tries < maxTries) {
    if (await option.isVisible()) { await option.click(); return; }
    await dropdown.evaluate((el) => { el.scrollBy(0, 100); });
    tries++;
  }
  throw new Error(`Unable to find global search filter option ...`);
};
